&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Exposure to data governance frameworks and metric catalogues&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:200}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
